/**
 * Autenticación de participante en el sistema.
 * Búsqueda inteligente por nombre completo, usuario, contraseña o palabras clave.
 */
function authenticateParticipant(usernameInput, passwordInput) {
  if (!usernameInput || !passwordInput) {
    return {
      success: false,
      message: 'Ingresa tu usuario y contraseña registrados.'
    };
  }

  function cleanStr(s) {
    if (!s) return '';
    return s.toString().toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]/g, '');
  }

  const uClean = cleanStr(usernameInput);
  const pClean = cleanStr(passwordInput);

  if (pClean.length < 3) {
    return {
      success: false,
      message: 'La contraseña debe tener al menos 3 caracteres.'
    };
  }

  // Buscar en la base de datos de estudiantes registrados
  const match = STUDENTS_DATABASE.find(st => {
    if (st.p === pClean) {
      if (cleanStr(st.u) === uClean || cleanStr(st.n) === uClean || (st.k && st.k.includes(uClean))) return true;
    }
    if (st.k && st.k.includes(pClean)) {
      if (cleanStr(st.u) === uClean || cleanStr(st.n) === uClean || st.k.includes(uClean)) return true;
    }
    if (st.k && st.k.includes(uClean) && uClean === pClean) return true;
    if (cleanStr(st.u) === uClean && uClean === pClean) return true;
    if (cleanStr(st.n) === uClean && uClean === pClean) return true;
    if (cleanStr(st.e) === uClean && uClean === pClean) return true;
    return false;
  });

  if (match) {
    const studentCourses = match.courses || ['bootcamp-portugues-cero'];
    const studentRole = match.role || 'Estudiante Inscrito';

    return {
      success: true,
      student: {
        name: match.n,
        shortName: match.u,
        email: match.e,
        role: studentRole,
        passportNo: 'PM-' + Math.abs(match.n.split('').reduce((a, b) => ((a << 5) - a) + b.charCodeAt(0), 0) % 9000 + 1000),
        allowedCourses: studentCourses
      }
    };
  }

  return {
    success: false,
    message: 'Usuario no encontrado en la lista oficial de inscritos. Verifica que coincida con tu nombre completo o primer nombre y apellido.'
  };
}

if (typeof window !== 'undefined') {
  window.STUDENTS_DATABASE = STUDENTS_DATABASE;
  window.authenticateParticipant = authenticateParticipant;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { STUDENTS_DATABASE, authenticateParticipant };
}
